#!/usr/bin/env node
/*
 * Builds supabase/kfc_apply_0104z_0106-0134.sql: every migration the KeyForCars
 * database (lzdwxkhlscsitstxdgar, at 0105) still needs, in order, in ONE
 * transaction — all or nothing. See docs/keyforcars-installatie.md.
 *
 *   node scripts/build-kfc-migration-bundle.mjs           write the bundle
 *   node scripts/build-kfc-migration-bundle.mjs --check   exit 1 when the committed bundle is stale
 *
 * Rebuild after every merge that adds a migration (the parallel branches own
 * 0129–0134; until they are merged the bundle lists them as missing).
 *
 * Writes a file only. It never connects to a database.
 */
import { createHash } from 'node:crypto';
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const MIGRATIONS = join(ROOT, 'supabase', 'migrations');
export const OUTPUT = join(ROOT, 'supabase', 'kfc_apply_0104z_0106-0134.sql');

/** The KeyForCars database is at 0105; 0104z was written after it and never ran there. */
const FIRST = 106;
const LAST_EXPECTED = 134;

/** Numbers reserved by parallel branches on 21 Nov 2026, so a missing one is named. */
export const RESERVED = {
  129: 'kassa / POS',
  130: 'cariler: klanten + leveranciers',
  131: 'voorraadrapporten',
  132: 'Woo voorraadsync + retouren',
  133: 'installatiemarkering (crm_install)',
  134: 'productdata / categorieën / gebruikers',
};

/** 0104z plus every NNNN_*.sql from 0106 on, in number order. */
export function selectMigrations(names) {
  const numbered = names
    .filter((name) => /^\d{4}_.+\.sql$/.test(name))
    .map((name) => ({ name, number: Number(name.slice(0, 4)) }))
    .filter(({ number }) => number >= FIRST)
    .sort((a, b) => a.number - b.number || a.name.localeCompare(b.name));
  const park = names.filter((name) => /^0104z_.+\.sql$/.test(name)).sort();
  const numbers = new Set(numbered.map(({ number }) => number));
  const missing = [];
  for (let number = FIRST; number <= LAST_EXPECTED; number += 1) if (!numbers.has(number)) missing.push(number);
  const counts = new Map();
  for (const { number } of numbered) counts.set(number, (counts.get(number) ?? 0) + 1);
  const duplicates = [...counts].filter(([, count]) => count > 1).map(([number]) => number);
  return { files: [...park, ...numbered.map(({ name }) => name)], missing, duplicates };
}

/** Statements that would end or break the one wrapping transaction. */
const NOT_IN_A_TRANSACTION = [
  /^\s*(begin|start\s+transaction|commit|rollback)\s*;/im,
  /\bconcurrently\b/i,
  /^\s*vacuum\b/im,
  /\balter\s+type\b[^;]*\badd\s+value\b/i,
];

export function transactionProblem(sql) {
  // Comments may mention these words; only code counts.
  const code = sql.replace(/\/\*[\s\S]*?\*\//g, '').replace(/--[^\n]*/g, '');
  const hit = NOT_IN_A_TRANSACTION.find((pattern) => pattern.test(code));
  return hit ? `contains ${hit}` : null;
}

const pad = (number) => String(number).padStart(4, '0');

export function buildBundle(migrations, { missing = [], duplicates = [] } = {}) {
  if (duplicates.length) throw new Error(`Two migrations share a number: ${duplicates.map(pad).join(', ')}. Renumber before bundling.`);
  for (const { name, sql } of migrations) {
    const problem = transactionProblem(sql);
    if (problem) throw new Error(`${name} cannot run inside the bundle's transaction: ${problem}`);
  }
  const list = migrations.map(({ name, sql }) => `--   ${name}  sha256:${createHash('sha256').update(sql).digest('hex').slice(0, 12)}`);
  const gaps = missing.map((number) => `--   ${pad(number)}  ${RESERVED[number] ?? '(no file)'}  — NOT IN THIS BUNDLE`);
  const header = [
    '-- KeyForCars database (lzdwxkhlscsitstxdgar): migrations after 0105, all or nothing.',
    '-- GENERATED by scripts/build-kfc-migration-bundle.mjs — do not edit; rebuild after merges.',
    '-- Runbook: docs/keyforcars-installatie.md. Run ONCE in the Supabase SQL editor of the',
    '-- KeyForCars project, after a backup. If any statement fails, nothing is changed.',
    '--',
    '-- Contains:',
    ...list,
    ...(gaps.length
      ? ['--', '-- Missing (not merged yet when this file was built — rebuild before go-live):', ...gaps]
      : []),
    '',
    'begin;',
    '',
    '-- Refuse the wrong database before touching anything.',
    '-- crm_install is read with EXECUTE: a static reference is planned even when',
    '-- the table is missing (KeyForCars at 0105 has none) and would abort the file.',
    'do $$',
    'declare v_marked text;',
    'begin',
    "  if to_regclass('public.inbox_threads') is null then",
    "    raise exception 'This database is not at migration 0105 (public.inbox_threads missing). Stop: wrong project, or 0001-0105 not applied.';",
    '  end if;',
    "  if to_regclass('public.crm_install') is not null then",
    "    execute 'select profile from public.crm_install limit 1' into v_marked;",
    '  end if;',
    "  if v_marked is not null and v_marked <> 'keyforcars' then",
    "    raise exception 'public.crm_install says this database is not KeyForCars. Stop.';",
    '  end if;',
    '  -- Autosleutel24 already has 0106+. A database that does, and is not marked',
    '  -- keyforcars, is not the one this file is for.',
    "  if to_regclass('public.whatsapp_quotes') is not null and coalesce(v_marked, '') <> 'keyforcars' then",
    "    raise exception 'This database already has migration 0106 and is not marked keyforcars (Autosleutel24?). Stop.';",
    '  end if;',
    'end',
    '$$;',
    '',
  ];
  const body = migrations.flatMap(({ name, sql }) => [`-- ===== ${name} =====`, sql.trimEnd(), '']);
  return [...header, ...body, 'commit;', ''].join('\n');
}

export function buildFromDisk() {
  const { files, missing, duplicates } = selectMigrations(readdirSync(MIGRATIONS));
  const migrations = files.map((name) => ({ name, sql: readFileSync(join(MIGRATIONS, name), 'utf8') }));
  return { sql: buildBundle(migrations, { missing, duplicates }), files, missing };
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const { sql, files, missing } = buildFromDisk();
  if (process.argv.includes('--check')) {
    const current = existsSync(OUTPUT) ? readFileSync(OUTPUT, 'utf8') : '';
    if (current !== sql) {
      console.error('supabase/kfc_apply_0104z_0106-0134.sql is stale: run node scripts/build-kfc-migration-bundle.mjs');
      process.exit(1);
    }
    console.log('Bundle is up to date.');
  } else {
    writeFileSync(OUTPUT, sql);
    console.log(`Wrote ${OUTPUT} with ${files.length} migrations (${files[0]} … ${files.at(-1)}).`);
  }
  if (missing.length) console.warn(`Missing: ${missing.map(pad).join(', ')} — rebuild after those branches are merged.`);
}
